class ThroneInheritance {
    private Map<String, List<String>> children = new HashMap<>();
    private Set<String> dead = new HashSet<>();
    private String king;

    public ThroneInheritance(String kingName) {
        king = kingName;
    }

    public void birth(String parentName, String childName) {
        children.computeIfAbsent(parentName, k -> new ArrayList<>()).add(childName);
    }

    public void death(String name) {
        dead.add(name);
    }

    public List<String> getInheritanceOrder() {
        List<String> order = new ArrayList<>();
        Deque<String> stack = new ArrayDeque<>();
        stack.push(king);
        while (!stack.isEmpty()) {
            String x = stack.pop();
            if (!dead.contains(x)) order.add(x);
            List<String> cs = children.get(x);
            if (cs == null) continue;
            for (int i = cs.size() - 1; i >= 0; i--) stack.push(cs.get(i));
        }
        return order;
    }
}

